  assert.equal(result.stderr, '');
});
test('help succeeds with usage and no greeting', () => {
  const result = run('--help');
  assert.equal(result.status, 0);
  assert.equal(result.stdout, 'Usage: greenfield-proof [name]\\n       greenfield-proof --help\\n');
  assert.equal(result.stderr, '');
});
test('unknown options fail with usage', () => {
  const result = run('--unknown');
  assert.equal(result.status, 1);
  assert.equal(result.stdout, '');
  assert.match(result.stderr, /Usage: greenfield-proof/);
});
test('blank names fail with usage', () => {
  const result = run('   ');
  assert.equal(result.status, 1);
  assert.equal(result.stdout, '');
